/* @lc app=leetcode id=3983 lang=kotlin */ class Solution { fun canMakeSubsequence(s: String, t: String): Boolean = (Int.MAX_VALUE / 2).let { INF -> s.fold(listOf(0)) { L, c -> L + (if (L.last() >= INF) INF else t.indexOf(c, L.last()).let { if (it < 0) INF else it + 1 }) }.let { L -> s.reversed().fold(listOf(t.length)) { R, c -> R + t.lastIndexOf(c, R.last() - 1) }.reversed().let { R -> s.indices.any { L[it] < R[it + 1] } } } } }